<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'

type Role = '學生' | '老師' | '家長'
const activeRole = ref<Role>('學生')
const menuOpen = ref(false)
const theme = ref<'dark' | 'light'>('dark')
const prompt = ref('我不太懂二次函數的頂點，可以用圖像解釋嗎？')
const response = ref('好問題！我們先把它拆成一個可以看見的學習路徑。')
const isThinking = ref(false)
const canvas = ref<HTMLCanvasElement | null>(null)
let cleanupScene: (() => void) | undefined
const roleContent: Record<Role, { eyebrow: string; title: string; description: string; metric: string; action: string }> = {
  學生: { eyebrow: '你的學習副駕', title: '讓每一次「為什麼」\n都變成下一步。', description: 'AI Tutor 不是給你答案，而是陪你找到自己的答案。把困惑丟進來，從今天開始建立真正屬於你的學習路徑。', metric: '12 min', action: '開始探索' },
  老師: { eyebrow: '你的教學副駕', title: '把每個學生的\n理解，清楚看見。', description: '從備課、題庫到即時回饋，讓 AI 接住重複工作，把時間留給真正重要的教學對話。', metric: '4.8x', action: '查看教學工具' },
  家長: { eyebrow: '你的成長視窗', title: '看見努力之外，\n也看見進步的方向。', description: '用清楚的學習脈絡取代模糊的分數焦慮，與孩子一起找到下一個值得突破的節點。', metric: '86%', action: '了解學習報告' },
}
const current = computed(() => roleContent[activeRole.value])
function sendPrompt() {
  if (!prompt.value.trim() || isThinking.value) return
  isThinking.value = true
  window.setTimeout(() => {
    response.value = activeRole.value === '學生' ? '先想像一座山：頂點就是函數的最高點。拖動右側的星核，看看它如何改變你的解題視角。' : activeRole.value === '老師' ? '我可以把這個概念整理成一組分層提示，讓不同程度的學生都能從自己的節點開始。' : '我會把「已完成、正在練習、下一步」整理成一張簡單的成長地圖。'
    isThinking.value = false
  }, 720)
}
function scrollTo(id: string) { document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' }); menuOpen.value = false }
onMounted(async () => {
  await nextTick()
  if (!canvas.value) return
  const THREE = await import('three')
  const scene = new THREE.Scene()
  const camera = new THREE.PerspectiveCamera(42, canvas.value.clientWidth / canvas.value.clientHeight, 0.1, 100)
  camera.position.set(0, 0.2, 7.2)
  const renderer = new THREE.WebGLRenderer({ canvas: canvas.value, alpha: true, antialias: true })
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2)); renderer.setSize(canvas.value.clientWidth, canvas.value.clientHeight, false); renderer.outputColorSpace = THREE.SRGBColorSpace
  const group = new THREE.Group(); scene.add(group)
  const core = new THREE.Mesh(new THREE.IcosahedronGeometry(1.02, 3), new THREE.MeshStandardMaterial({ color: 0xffb84d, emissive: 0x8a4d08, emissiveIntensity: 0.65, roughness: 0.28, metalness: 0.18, flatShading: true })); group.add(core)
  const wire = new THREE.Mesh(new THREE.IcosahedronGeometry(1.28, 2), new THREE.MeshBasicMaterial({ color: 0xffca6b, wireframe: true, transparent: true, opacity: 0.32 })); group.add(wire)
  const ring = new THREE.Mesh(new THREE.TorusGeometry(1.7, 0.012, 10, 120), new THREE.MeshBasicMaterial({ color: 0x68e3c4, transparent: true, opacity: 0.7 })); ring.rotation.x = Math.PI * 0.62; group.add(ring)
  const ring2 = ring.clone(); ring2.scale.set(0.74, 0.74, 0.74); ring2.rotation.y = Math.PI * 0.54; ring2.material = (ring.material as THREE.MeshBasicMaterial).clone(); (ring2.material as THREE.MeshBasicMaterial).color.set(0xff7b68); group.add(ring2)
  const stars = new THREE.BufferGeometry(); const positions = new Float32Array(330)
  for (let i = 0; i < positions.length; i += 3) { const r = 2.1 + Math.random() * 2.6; const theta = Math.random() * Math.PI * 2; const phi = Math.acos((Math.random() * 2) - 1); positions[i] = r * Math.sin(phi) * Math.cos(theta); positions[i + 1] = r * Math.sin(phi) * Math.sin(theta); positions[i + 2] = r * Math.cos(phi) }
  stars.setAttribute('position', new THREE.BufferAttribute(positions, 3)); const starField = new THREE.Points(stars, new THREE.PointsMaterial({ color: 0x9af5dc, size: 0.025, transparent: true, opacity: 0.68 })); scene.add(starField)
  scene.add(new THREE.AmbientLight(0xffffff, 1.4)); const light = new THREE.PointLight(0xffb84d, 14, 8); light.position.set(2, 2, 3); scene.add(light)
  let frame = 0
  const animate = () => { frame = requestAnimationFrame(animate); const t = performance.now() * 0.0005; group.rotation.y = t * 0.48; group.rotation.x = Math.sin(t * 0.7) * 0.08; ring.rotation.z = t * 0.35; ring2.rotation.z = -t * 0.58; starField.rotation.y = -t * 0.08; renderer.render(scene, camera) }
  const resize = () => { if (!canvas.value) return; camera.aspect = canvas.value.clientWidth / canvas.value.clientHeight; camera.updateProjectionMatrix(); renderer.setSize(canvas.value.clientWidth, canvas.value.clientHeight, false) }
  window.addEventListener('resize', resize); animate(); cleanupScene = () => { cancelAnimationFrame(frame); window.removeEventListener('resize', resize); renderer.dispose() }
})
onBeforeUnmount(() => cleanupScene?.())
</script>

<template>
  <div class="site-shell" :class="{ 'light-mode': theme === 'light' }">
    <header class="topbar">
      <a class="brand" href="#top" @click.prevent="scrollTo('top')"><span class="brand-mark"><span></span><span></span><span></span></span><span>AI<span class="brand-muted">TUTOR</span></span></a>
      <nav class="desktop-nav"><button @click="scrollTo('how-it-works')">怎麼運作</button><button @click="scrollTo('roles')">為誰而生</button><button @click="scrollTo('demo')">互動體驗</button></nav>
      <div class="top-actions"><button class="theme-toggle" @click="theme = theme === 'dark' ? 'light' : 'dark'">{{ theme === 'dark' ? '☼' : '◐' }}</button><button class="login-link" @click="scrollTo('demo')">登入</button><button class="header-cta" @click="scrollTo('demo')">免費開始 <span>↗</span></button><button class="menu-toggle" @click="menuOpen = !menuOpen">☰</button></div>
    </header>
    <div v-if="menuOpen" class="mobile-menu"><button @click="scrollTo('how-it-works')">怎麼運作</button><button @click="scrollTo('roles')">為誰而生</button><button @click="scrollTo('demo')">互動體驗</button></div>
    <main id="top">
      <section class="hero section-grid"><div class="hero-copy"><div class="eyebrow"><span class="pulse-dot"></span>{{ current.eyebrow }}</div><h1>{{ current.title }}</h1><p class="hero-description">{{ current.description }}</p><div class="hero-actions"><button class="primary-button" @click="scrollTo('demo')">{{ current.action }} <span>↗</span></button><button class="text-button" @click="scrollTo('how-it-works')">先了解 AI Tutor <span>↓</span></button></div><div class="trust-line"><div class="avatar-stack"><span>Y</span><span>K</span><span>J</span><span>+</span></div><span>和 2,000+ 位學習者一起前進</span></div></div><div class="hero-visual"><div class="visual-label label-top"><span class="label-line"></span>學習節點 <b>03</b></div><div class="canvas-wrap"><canvas ref="canvas"></canvas><div class="orbit-caption">drag to explore<br><span>你的下一步，正在生成</span></div></div><div class="visual-label label-bottom"><span>即時回饋</span><i></i><span>個人路徑</span></div></div><div class="hero-note"><span>01</span><span>不是更快完成，而是更深理解。</span><span class="note-arrow">↘</span></div></section>
      <section id="how-it-works" class="proof-band"><div><span class="section-kicker">/ AI TUTOR METHOD</span><h2>把學習變成<br><em>可見的旅程。</em></h2></div><div class="proof-copy"><p>每一次提問，都會留下理解的痕跡。AI Tutor 將對話、練習與回饋串成一張會呼吸的學習地圖。</p><div class="method-row"><span>提問</span><i>→</i><span>理解</span><i>→</i><span>成長</span></div></div></section>
      <section id="roles" class="roles-section"><div class="section-heading"><div><span class="section-kicker">/ ONE SPACE, THREE PERSPECTIVES</span><h2>從你的角度，<br>開始一場對話。</h2></div><p>學習不只有一種樣子。選擇你的角色，看看 AI Tutor 如何陪你走下一步。</p></div><div class="role-tabs"><button v-for="role in (['學生', '老師', '家長'] as Role[])" :key="role" :class="{ active: activeRole === role }" @click="activeRole = role">{{ role }} <span>{{ role === '學生' ? '01' : role === '老師' ? '02' : '03' }}</span></button></div></section>
      <section id="demo" class="demo-section"><div class="demo-intro"><span class="section-kicker">/ TRY THE CONVERSATION</span><h2>先問一個<br><em>好問題。</em></h2><p>這是一個互動示範。真正的 AI Tutor 會依照你的學習脈絡，陪你從卡住的地方開始。</p><div class="metric"><strong>{{ current.metric }}</strong><span>平均一次理解循環</span></div></div><div class="chat-card"><div class="chat-top"><span class="status-dot"></span><span>AI Tutor · 線上</span><span class="chat-more">•••</span></div><div class="chat-body"><div class="chat-message tutor"><span class="mini-avatar">AI</span><p>{{ response }}</p></div><div class="chat-message user"><p>{{ prompt }}</p></div><div class="suggestions"><button @click="prompt = '怎麼準備下週的數學考試？'; sendPrompt()">幫我規劃複習</button><button @click="prompt = '我想把錯題真正弄懂。'; sendPrompt()">分析我的錯題</button></div></div><form class="chat-input" @submit.prevent="sendPrompt"><input v-model="prompt" aria-label="輸入問題" placeholder="輸入你的問題…"><button type="submit" :disabled="isThinking">{{ isThinking ? '…' : '↑' }}</button></form></div></section>
      <section class="final-cta"><div class="final-glow"></div><span class="section-kicker">/ YOUR NEXT CHAPTER</span><h2>學習，從一個<br><em>好問題開始。</em></h2><button class="primary-button" @click="scrollTo('demo')">開始你的探索 <span>↗</span></button><div class="final-index">AI TUTOR / 2026</div></section>
    </main>
    <footer><a class="brand" href="#top" @click.prevent="scrollTo('top')"><span class="brand-mark"><span></span><span></span><span></span></span><span>AI<span class="brand-muted">TUTOR</span></span></a><span>給每個好奇的人，一條更清楚的路。</span><span>© 2026 AI Tutor Team</span></footer>
  </div>
</template>

