mp(28px,4vw,60px);font-weight:500;letter-spacing:-.05em;padding:26px 0;cursor:pointer;text-align:left;transition:.25s}.role-tabs button span{font:11px 'DM Mono',monospace;letter-spacing:.06em}.role-tabs button.active{color:var(--ink);padding-left:28px}.role-tabs button.active:before{content:'↗';color:var(--mint);font:20px 'DM Mono',monospace;margin-right:12px}.role-tabs button:hover{color:var(--ink)}.demo-section{padding:120px clamp(24px,13vw,210px);background:var(--surface);display:grid;grid-template-columns:1fr 1fr;gap:14%;align-items:center}.demo-intro h2{font-size:clamp(50px,5.5vw,80px)}.metric{display:flex;align-items:baseline;gap:14px;border-top:1px solid var(--line);margin-top:55px;padding-top:18px}.metric strong{font-size:35px;color:var(--orange);font-weight:500}.metric span{color:var(--muted);font:10px 'DM Mono',monospace}.chat-card{border:1px solid var(--line);background:var(--bg);box-shadow:0 22px 70px #0000002b}.chat-top{padding:17px 21px;border-bottom:1px solid var(--line);font:10px 'DM Mono',monospace;color:var(--muted)}.chat-top .status-dot{margin-right:8px;width:5px;height:5px}.chat-more{float:right;color:var(--orange);letter-spacing:3px}.chat-body{padding:24px;min-height:290px}.chat-message{display:flex;gap:12px;margin:0 0 20px;max-width:90%}.chat-message p{font-size:13px;line-height:1.6;margin:0;padding:12px 15px;background:var(--surface);color:var(--muted)}.chat-message.user{margin-left:auto;justify-content:flex-end}.chat-message.user p{background:#273e39;color:var(--mint)}.mini-avatar{width:25px;height:25px;display:grid;place-items:center;background:var(--orange);color:#111315;font:9px 'DM Mono',monospace;flex:none}.suggestions{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0 0 37px}.suggestions button{background:none;border:1px solid var(--line);color:var(--muted);font:10px 'DM Mono',monospace;padding:8px 10px;cursor:pointer}.suggestions button:hover{border-color:var(--mint);color:var(--mint)}.chat-input{display:flex;border-top:1px solid var(--